import os
from pathlib import Path
import subprocess
import tempfile
import unittest
from haxe_test_support import HAXE_COMMAND
from source_attachment_fixture_support import attachment_fixture_files
from test_nv_multifield_routes import method
ROOT=Path(__file__).resolve().parents[2]

def integration_files():
 files=attachment_fixture_files()
 files['PsychFlxCameraCompat.hx']='class PsychFlxCameraCompat {public function getField(f:String):Dynamic return null;public function setField(f:String,v:Dynamic):Dynamic return v;}class PsychFlxGCompat {public static function getField(f:String):Dynamic return null;public static function setField(f:String,v:Dynamic):Dynamic return v;}'
 files['NightmareVisionPlayableSongOwner.hx']='interface NightmareVisionPlayableSongOwner {public function nightmareVisionAudioView():Dynamic;}'
 files['NightmareVisionFlxGView.hx']='class NightmareVisionFlxGView {public static function releaseForSave(v:Dynamic):Void{}public function getField(f:String):Dynamic return null;public function setField(f:String,v:Dynamic):Dynamic return v;}'
 files['Character.hx']='class Character {public var animation:Dynamic;}'
 files['PsychBaseStageActorGroupCompat.hx']='class PsychBaseStageActorGroupCompat {}'
 files['HxcCompatRuntime.hx']='class HxcCompatRuntime {public static function getZIndex(o:Dynamic):Dynamic return 0;public static function setZIndex(o:Dynamic,v:Dynamic):Dynamic return v;}'
 files['OptionsHandler.hx']='class OptionsHandler {public static var options={antialiasing:false};}'
 files['PsychOwnerPaths.hx']='class PsychOwnerPaths {public static function create(r:String,?l:String):Dynamic return new AttachmentFacade(r);}'
 files['AttachmentFacade.hx']='class AttachmentFacade {public var root:String;public var log:Array<String>=[];public var fail=false;public function new(r:String)root=r;public function image(s:String,?f:String):flixel.graphics.FlxGraphic {log.push(root+":image:"+s+":"+f);if(fail)throw "owner-load-failed";return new flixel.graphics.FlxGraphic(root=="a"?33:55,27);}public function getSparrowAtlas(s:String,?f:String):flixel.graphics.frames.FlxAtlasFrames {log.push(root+":atlas:"+s+":"+f);if(fail)throw "owner-load-failed";return new flixel.graphics.frames.FlxAtlasFrames();}}'
 ps=(ROOT/'source/PlayState.hx').read_text()
 methods='\n'.join(method(ps,n).replace('function ','public function ',1) for n in ['function sourceAttachedSpriteOwner(','function bindSourceAttachmentClasses('])
 files['AttachmentHost.hx']='import flixel.util.FlxAxes;class AttachmentHost extends flixel.group.FlxGroup.FlxTypedGroup<flixel.FlxBasic> {public var psychStageLibrary:String;public var psychClientPrefs:Dynamic={data:{antialiasing:true}};public function new(){super();}function selectedPsychSkinRoot():String return "current";'+methods+'}'
 return files

class SourceAttachmentIntegrationTest(unittest.TestCase):
 def test_psych_owner_factory_plain_bridge_assets_and_once_only_display(self):
  files=integration_files()
  files['Main.hx']=r'''import flixel.FlxBasic;import flixel.FlxSprite;
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function near(a:Float,b:Float):Void if(Math.abs(a-b)>.00001)throw "value "+a+" != "+b;static function main(){var a=new AttachmentFacade("a");var b=new AttachmentFacade("b");var h=new AttachmentHost();var h2=new AttachmentHost();h2.psychClientPrefs.data.antialiasing=false;var one=new SourceIrisBridge(h);var two=new SourceIrisBridge(h2);h.bindSourceAttachmentClasses(one.evaluator,false,a);h2.bindSourceAttachmentClasses(two.evaluator,false,b);one.variables.set("game",h);one.variables.set("FlxSprite",FlxSprite);one.evaluate("import objects.AttachedSprite; import flixel.util.FlxAxes; empty=new AttachedSprite(); staticSprite=new AttachedSprite('block',null,'week',false); animated=new AttachedSprite('atlas','idle','shared',true); qualified=new objects.AttachedSprite('block'); tracker=new FlxSprite(12,34); staticSprite.sprTracker=tracker; staticSprite.xAdd=7; staticSprite.yAdd=-2; staticSprite.angleAdd=9; staticSprite.alphaMult=.4; staticSprite.copyVisible=true; game.add(tracker); game.add(staticSprite);", "attached-psych.hx");two.evaluate("import objects.AttachedSprite; other=new AttachedSprite('block',null,'week');", "other-owner.hx");var empty:PsychSourceAttachedSprite=cast one.variables.get("empty");var sprite:PsychSourceAttachedSprite=cast one.variables.get("staticSprite");var tracker:FlxSprite=cast one.variables.get("tracker");var animated:PsychSourceAttachedSprite=cast one.variables.get("animated");var qualified:PsychSourceAttachedSprite=cast one.variables.get("qualified");var other:PsychSourceAttachedSprite=cast two.variables.get("other");ok(Std.isOfType(sprite,PsychSourceAttachedSprite)&&Std.isOfType(sprite,FlxSprite)&&Std.isOfType(sprite,FlxBasic),"realnative spriteidentity");ok(h.members.length==2&&h.members[1]==sprite,"one visible owned member");ok(a.log.join("|")=="a:image:block:week|a:atlas:atlas:shared|a:image:block:null","file/atlas/parentfolder exact capturedowner");ok(b.log.join("|")=="b:image:block:week"&&sprite.frameWidth==33&&other.frameWidth==55,"ownerisolation independentofcurrentglobal");ok(sprite.antialiasing&&!other.antialiasing,"capturedstate preference");ok(empty.scrollFactor.x==0&&empty.scrollFactor.y==0,"sourceemptyconstructor");ok(animated.animation.curAnim.name=="idle"&&animated.animation.curAnim.looped,"animatedprefixloop actualcontroller");tracker.angle=40;tracker.alpha=.5;tracker.visible=false;tracker.scrollFactor.set(.2,.8);sprite.onUpdate=()->{tracker.x=50;tracker.y=70;};h.update(.1);near(sprite.x,57);near(sprite.y,68);near(sprite.angle,49);near(sprite.alpha,.2);ok(!sprite.visible&&sprite.scrollFactor.x==.2&&sprite.scrollFactor.y==.8,"postsuper copiedpresentation");ok(sprite.updates==1&&tracker.updates==1,"display updatedonce");sprite.sprTracker=null;sprite.x=123;h.update(.1);near(sprite.x,123);h.psychClientPrefs.data.antialiasing=false;one.evaluate("latest=new AttachedSprite();", "live-pref.hx");ok(!(cast one.variables.get("latest"):PsychSourceAttachedSprite).antialiasing,"live preference newconstructor");var before=a.log.length;one.evaluate("localCtor=AttachedSprite; local=localCtor;", "identity.hx");ok(one.variables.get("local")==PsychSourceAttachedSprite,"constructor classidentity");a.fail=true;var threw=false;try one.evaluate("failed=new AttachedSprite('missing');", "failed.hx")catch(e:Dynamic)threw=true;ok(threw&&a.log.length==before+1,"ownerload failure propagates");h.destroy();ok(sprite.destroyed==1&&tracker.destroyed==1,"state owns bothonce");ok(other.destroyed==0,"otherowner borrowedlifetime unchanged");empty.destroy();animated.destroy();qualified.destroy();other.destroy();one.release();two.release();}}
'''
  self.run_haxe(files,cpp=True)
 def test_nv_secondary_module_imports_axes_order_replacement_and_borrowed_lifetime(self):
  files=integration_files()
  files['Main.hx']=r'''import flixel.FlxBasic;import flixel.FlxObject;import flixel.FlxSprite;import flixel.util.FlxAxes;
class Main {static function ok(v:Bool,m:String):Void if(!v)throw m;static function near(a:Float,b:Float):Void if(Math.abs(a-b)>.00001)throw "value "+a+" != "+b;static function main(){var h=new AttachmentHost();var i=new NightmareVisionScriptInterp(h);h.bindSourceAttachmentClasses(i,true);i.variables.set("game",h);i.variables.set("FlxSprite",FlxSprite);i.variables.set("FlxObject",FlxObject);var p=new NightmareVisionScriptParser();i.execute(p.parseString("import funkin.objects.nodes.AttachedNode; moduleSprite=new AttachedSprite();"));ok(Std.isOfType(i.variables.get("moduleSprite"),NightmareVisionAttachedSprite),"primarymodule with source secondaryshortname");(cast i.variables.get("moduleSprite"):NightmareVisionAttachedSprite).destroy();i.execute(p.parseString("import funkin.objects.nodes.AttachedNode; import funkin.objects.nodes.AttachedNode.AttachedSprite; import flixel.util.FlxAxes; tracker=new FlxSprite(10,20); root=new FlxSprite(0,0); node=new AttachedNode(root,tracker); wrapper=new AttachedSprite(tracker); direct=new funkin.objects.nodes.AttachedNode.AttachedSprite(); node.copyAxis=FlxAxes.X; node.positionOffset.set(3,4); node.angleOffset=5; node.alphaMultiplier=.5; game.add(root); game.add(node); game.add(wrapper);"));var node:NightmareVisionAttachedNode=cast i.variables.get("node");var root:FlxSprite=cast i.variables.get("root");var tracker:FlxSprite=cast i.variables.get("tracker");var wrapper:NightmareVisionAttachedSprite=cast i.variables.get("wrapper");var direct:NightmareVisionAttachedSprite=cast i.variables.get("direct");ok(Std.isOfType(node,FlxBasic)&&!Std.isOfType(node,FlxSprite)&&Std.isOfType(wrapper,FlxSprite),"actualnode/sprite classidentities");ok(wrapper.attachedNode.root==wrapper&&wrapper.attachedNode.tracked==tracker&&direct.attachedNode.tracked==null,"ownedwrappernode sourceconstructor");ok(i.importBindings.get("funkin.objects.nodes.AttachedNode")==NightmareVisionAttachedNode&&i.importBindings.get("funkin.objects.nodes.AttachedNode.AttachedSprite")==NightmareVisionAttachedSprite,"exactsecondary module binding");ok(!i.importBindings.exists("funkin.objects.nodes.AttachedSprite"),"no inventedflat sourceimport");tracker.angle=30;tracker.alpha=.6;tracker.visible=false;tracker.scrollFactor.set(.4,.7);node.onUpdate=()->{tracker.x=40;tracker.y=60;};wrapper.onUpdate=()->{tracker.y=90;};h.update(.1);near(root.x,43);near(root.y,0);near(root.angle,35);near(root.alpha,.3);ok(!root.visible&&root.scrollFactor.x==1,"nodecopiesno scrollfactor");near(wrapper.x,40);near(wrapper.y,90);ok(node.updates==1&&wrapper.updates==1&&wrapper.attachedNode.updates==1,"hierarchyupdates onlyownednode once");i.execute(p.parseString("node.copyAxis=FlxAxes.NONE; root.x=7; root.y=8; node.copyAlpha=false; node.copyAngle=false; node.copyVisibility=false;"));node.update(.1);near(root.x,7);near(root.y,8);ok((cast node.copyAxis:Int)==0,"NONE facade exactvalue");var replacement=new FlxObject(100,200);i.variables.set("replacement",replacement);i.execute(p.parseString("node.tracked=replacement; node.copyAxis=FlxAxes.XY; node.copyAlpha=true;"));node.update(.1);near(root.x,103);near(root.y,204);near(root.alpha,.3);ok(replacement.destroyed==0,"actualFlxObject alpha gate");var offset=node.positionOffset;node.destroy();ok(offset.puts==1&&root.destroyed==0&&replacement.destroyed==0&&tracker.destroyed==0,"node returns onlyownoffset");var inner=wrapper.attachedNode;var point=inner.positionOffset;wrapper.destroy();ok(wrapper.destroyed==1&&inner.destroyed==1&&point.puts==1&&tracker.destroyed==0,"wrapper destroysownednode only");direct.destroy();i.release();}}
'''
  self.run_haxe(files,cpp=True)
 def run_haxe(self,files,cpp=False):
  with tempfile.TemporaryDirectory(dir=ROOT/'tmp') as tmp:
   for name,content in files.items():
    p=Path(tmp)/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
   env=os.environ.copy();env['HAXEPATH']=str(ROOT/'.tools/haxe');env['NEKOPATH']=str(ROOT/'.tools/neko');env['HAXELIB_PATH']=str(ROOT/'.haxelib');env['PATH']=os.pathsep.join((env['HAXEPATH'],env['NEKOPATH'],env.get('PATH','')))
   command=[*HAXE_COMMAND,'-D','flixel','-cp',str(ROOT/'source'),'-cp',str(ROOT/'.haxelib/hscript/2,5,0'),'-cp',str(ROOT/'.haxelib/hscript-iris/1,1,3'),'-cp',tmp,'-main','Main']
   for args in ([['--interp'],['-cpp',str(Path(tmp)/'cpp'),'-D','no-compilation']] if cpp else [['--interp']]):
    r=subprocess.run(command+args,cwd=ROOT,env=env,capture_output=True,text=True,timeout=40)
    self.assertEqual(r.returncode,0,(r.stdout+r.stderr)[-4000:])
if __name__=='__main__':unittest.main()
